export var after_touko = [[0, "", "憧子毕业的一年后，我也顺利毕了业。", null, "空_青空", "bgm39", null, "After Story", null, null], [1, "", "之后我俩的生活也十分顺利。", null, "空_青空", "bgm39", null, "After Story", null, null], [2, "", "虽然彼此间有过小吵小闹，不过都是些鸡毛蒜皮的小事。", null, "空_青空", "bgm39", null, "After Story", null, null], [3, "", "反正肯定没闹到把关系搞僵。", null, "空_青空", "bgm39", null, "After Story", null, null], [4, "", "这样幸福的关系持续了好几年，我也已经走入社会能够自己赚钱了。", null, "空_青空", "bgm39", null, "After Story", null, null], [5, "", "话虽如此，但收入的数额也没什么好炫耀的，就是我这个年纪的平均值罢了。", null, "空_青空", "bgm39", null, "After Story", null, null], [6, "", "不过呢……能够自己赚钱养家，其实就算是一大变化了吧。所以——", null, "空_青空", "bgm39", null, "After Story", null, null], [7, "柊史", "「我想差不多是时候了吧」", null, "空_青空", "bgm39", null, "After Story", null, null], [8, "憧子", "「哎？你说什么？」", "tou412_001", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [9, "", "我突然的一句话，让憧子脑袋一歪，露出了讶异的表情。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [10, "", "这也难怪。毕竟我这句话说得真的很突然。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [11, "柊史", "「我现在也开始上班了。虽然算不上太多，但好歹也能拿到薪水了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [12, "憧子", "「嗯，是啊。你每天工作辛苦了」", "tou412_002", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [13, "柊史", "「所以我想差不多是时候了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [14, "憧子", "「所以你到底想说什么呀？」", "tou412_003", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [15, "柊史", "「……我是说结婚啊」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [16, "柊史", "「憧子，你愿意嫁给我吗？」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "23", "pose": "1"}, "After Story", null, null], [17, "憧子", "「……」", "tou412_004", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "06", "pose": "1"}, "After Story", null, null], [18, "憧子", "「……我说，小柊」", "tou412_005", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "23", "pose": "1"}, "After Story", null, null], [19, "柊史", "「我在，请问你有何指教？」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "23", "pose": "1"}, "After Story", null, null], [20, "憧子", "「这不是做梦吧……我真的不是在做梦吧」", "tou412_006", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "20", "pose": "3"}, "After Story", null, null], [21, "柊史", "「不是梦，这是现实」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "20", "pose": "3"}, "After Story", null, null], [22, "憧子", "「你现在正在对我求婚……我的意中人，正请求我嫁给他对吧？」", "tou412_007", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "32", "pose": "1"}, "After Story", null, null], [23, "柊史", "「没错。嫁给我，跟我一起生活吧。然后一起寻觅更多的幸福吧」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "32", "pose": "1"}, "After Story", null, null], [24, "柊史", "「我爱你，憧子」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "32", "pose": "1"}, "After Story", null, null], [25, "憧子", "「……我好开心……真的好开心啊……听到你这么说，我……我感觉我都要哭了」", "tou412_008", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25", "pose": "1"}, "After Story", null, null], [26, "柊史", "「我赚钱不多，可能要稍微委屈你了。不过我会继续努力的」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25", "pose": "1"}, "After Story", null, null], [27, "憧子", "「委屈什么啊。没事的，我也会努力的。我不但会把家务做好，有必要的话我也会继续工作」", "tou412_009", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [28, "憧子", "「能跟你在一起的话，这点事算不了什么」", "tou412_010", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "02", "pose": "1"}, "After Story", null, null], [29, "柊史", "「我也会努力的。为了能保护好你，从今往后要继续发愤图强！」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "02", "pose": "1"}, "After Story", null, null], [30, "憧子", "「……嗯」", "tou412_011", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "02", "pose": "1"}, "After Story", null, null], [31, "柊史", "「所以请让我正式说出这句话。跟我结婚吧，憧子。这回不是以后再说了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "02", "pose": "1"}, "After Story", null, null], [32, "憧子", "「好的，我很乐意」", "tou412_012", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "03", "pose": "1"}, "After Story", null, null], [33, "柊史", "「今后就请你多多指教了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "03", "pose": "1"}, "After Story", null, null], [34, "憧子", "「我才是，从今往后都要请你多多关照了」", "tou412_013", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [35, "", "我们向彼此低头致意。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "19", "pose": "1"}, "After Story", null, null], [36, "", "接着我们抬起头，看向彼此的眼睛", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "19", "pose": "1"}, "After Story", null, null], [37, "憧子＆柊史", "『……』", "tou412_014", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "23", "pose": "1"}, "After Story", null, null], [38, "憧子＆柊史", "「呵呵呵」「哈哈哈」", "tou412_015", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25h", "pose": "1"}, "After Story", null, null], [39, "", "然后不由自主地向对方羞涩一笑。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25h", "pose": "1"}, "After Story", null, null], [40, "", "交往了那么久，我们还是能保持当初的那种感觉。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25h", "pose": "1"}, "After Story", null, null], [41, "", "但是结了婚，彼此相处的时间更长了之后，这种氛围可能迟早会消失。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25h", "pose": "1"}, "After Story", null, null], [42, "柊史", "「不过好在是你答应了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "25h", "pose": "1"}, "After Story", null, null], [43, "憧子", "「呵呵，那么紧张干嘛。我怎么可能拒绝你的求婚呢。我的心意是不会改变的啊」", "tou412_016", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [44, "柊史", "「我也是这么想的，但总还是会担心」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [45, "憧子", "「唔……不过也是啊。结婚确实是一件大事」", "tou412_017", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "32", "pose": "1"}, "After Story", null, null], [46, "憧子", "「但我真的很开心……到现在我总算能说了，其实我一直在等呢。盼星星盼月亮就盼这一天到来」", "tou412_018", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [47, "柊史", "「原、原来是这样。对不起，让你久等了」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "26", "pose": "1"}, "After Story", null, null], [48, "憧子", "「不会啦，已经没事了，毕竟你现在已经跟我求婚了……谢谢你」", "tou412_019", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [49, "柊史", "「我才要感谢你」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [50, "", "啊……真的松了一口气。", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [51, "柊史", "「那么憧子，跟我一起去买东西吧？」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "14", "pose": "1"}, "After Story", null, null], [52, "憧子", "「买东西？」", "tou412_020", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "33", "pose": "1"}, "After Story", null, null], [53, "柊史", "「去买戒指吧。去买比之前那个更加正式的戒指，然后再去看看筹办婚礼的宣传册」", null, "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "33", "pose": "1"}, "After Story", null, null], [54, "憧子", "「……嗯！」", "tou412_021", "ヒロイン_憧子の部屋m", "bgm39", {"char": "憧子", "dress": "部屋着", "face": "02h", "pose": "1"}, "After Story", null, null], [55, "", "那天我们带着兴奋的心情逛遍了大街小巷。", null, "空_青空", "bgm34", null, "After Story", null, null], [56, "", "不但看了订婚戒指，看了婚礼会场，还顺便看了蜜月旅行目的地的宣传单。", null, "空_青空", "bgm34", null, "After Story", null, null], [57, "", "我们兴致奇高，仅仅是看着心里就雀跃不已。", null, "空_青空", "bgm34", null, "After Story", null, null], [58, "", "甚至逛到都忘了时间。", null, "空_青空", "bgm34", null, "After Story", null, null], [59, "", "快乐的时光真的是转瞬即逝，回过神来才发现太阳早已下山，夜晚已经到来。", null, "空_夜空", "bgm34", null, "After Story", null, null], [60, "", "顺便一提，我们这一整天的时间真的都花在了逛街上。", null, "空_夜空", "bgm34", null, "After Story", null, null], [61, "柊史", "「真的可以吗？订会场是没那么急，但戒指至少该在今天买下来吧」", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [62, "憧子", "「没事。不用那么着急，你有这份心我就很开心了。不过这事我想好好考虑一下」", "tou412_022", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "32", "pose": "1"}, "After Story", null, null], [63, "憧子", "「毕竟这可是一生一次的经历啊。我们俩的话肯定不会再有下回的」", "tou412_023", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "02", "pose": "1"}, "After Story", null, null], [64, "憧子", "「所以呢，后悔是肯定不会后悔的……但我还是想好好考虑一下。不用那么急着订会场买婚戒的」", "tou412_024", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "20", "pose": "3"}, "After Story", null, null], [65, "憧子", "「就把这个婚礼办到让彼此都满意吧」", "tou412_025", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "15", "pose": "3"}, "After Story", null, null], [66, "柊史", "「……好。你说的也有道理」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "15", "pose": "3"}, "After Story", null, null], [67, "憧子", "「不过我也没打算无限期地拖下去」", "tou412_026", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "09", "pose": "2"}, "After Story", null, null], [68, "柊史", "「我明白。反正我是随时都行的」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "09", "pose": "2"}, "After Story", null, null], [69, "憧子", "「嗯，谢谢你」", "tou412_027", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "20", "pose": "2"}, "After Story", null, null], [70, "", "虽然没有任何实质性的收获……不过这一天仍然过得十分充实。", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [71, "", "虽然逛了一整天两条腿有点吃不消就是了。", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [72, "柊史", "「那么差不多该回家了吧？」", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [73, "", "我边说边准备踏上归途时，憧子忽然拉住了我的衣袖。", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [74, "柊史", "「……那个，有什么事吗？」", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [75, "憧子", "「听我说……那个……我们不是马上要结婚了吗？」", "tou412_028", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "05h", "pose": "3"}, "After Story", null, null], [76, "柊史", "「是啊。确实如此」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "05h", "pose": "3"}, "After Story", null, null], [77, "憧子", "「我从小就是孤身一人……所以对家庭……一直都很憧憬」", "tou412_029", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "29h", "pose": "2"}, "After Story", null, null], [78, "柊史", "「我也很向往温馨的家庭生活啊」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "29h", "pose": "2"}, "After Story", null, null], [79, "憧子", "「嗯。所以……呃，那个……虽然戒指是一定要的，但我还有另一样想要的东西」", "tou412_030", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "05h", "pose": "3"}, "After Story", null, null], [80, "柊史", "「……」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "05h", "pose": "3"}, "After Story", null, null], [81, "憧子", "「所以呢，我想那个应该可以解禁了」", "tou412_031", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "06h", "pose": "2"}, "After Story", null, null], [82, "柊史", "「你说的那个是指……」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "06h", "pose": "2"}, "After Story", null, null], [83, "憧子", "「就是那个啦…………不、不戴套之类的……」", "tou412_032", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [84, "柊史", "「不戴套……」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [85, "柊史", "「不戴套？！」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [86, "", "没错，在憧子体内的魔法失效之后，我们就开始戴套以规避计划外的受孕。", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [87, "", "不过……说的也是，毕竟都要结婚了，已经可以解禁了吧。", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [88, "", "虽然结婚还没那么快……不过孩子从怀孕到出生也是要时间的。", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [89, "", "既然如此……", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "11h", "pose": "2"}, "After Story", null, null], [90, "憧子", "「小柊……你是不是觉得得先把日子完全定下来才能解禁呢？」", "tou412_033", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "19h", "pose": "3"}, "After Story", null, null], [91, "柊史", "「不……没那回事。只要接下来我们每周都……不，每天都把结婚的事考虑起来，别把结论无限延后就行了吧？」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "19h", "pose": "3"}, "After Story", null, null], [92, "憧子", "「对、对吧？你也这么想吧？」", "tou412_034", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "27h", "pose": "1"}, "After Story", null, null], [93, "柊史", "「是的」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "27h", "pose": "1"}, "After Story", null, null], [94, "", "……好、好久没有不戴套了。", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [95, "", "不好，我要兴奋得憋不住了……", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [96, "柊史", "「那个！憧子！」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "23", "pose": "1"}, "After Story", null, null], [97, "憧子", "「什、什么事？」", "tou412_035", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "33", "pose": "1"}, "After Story", null, null], [98, "柊史", "「我、我们……今天在那里住一晚吧？」", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "33", "pose": "1"}, "After Story", null, null], [99, "憧子", "「那里是指……啊……」", "tou412_036", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "03", "pose": "3"}, "After Story", null, null], [100, "", "我的视线前方，出现了一座那种用途的特殊旅馆。", null, "外_繁華街モブc", "bgm34", null, "After Story", null, null], [101, "", "看到它之后，憧子一下子变得满脸通红。", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "29h", "pose": "2"}, "After Story", null, null], [102, "", "但是她始终没有摇头……", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "29h", "pose": "2"}, "After Story", null, null], [103, "憧子", "「……好……」", "tou412_037", "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [104, "", "她悄咪咪地点了点头。", null, "外_繁華街モブc", "bgm34", {"char": "憧子", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [105, "憧子", "「嗯啾，啾……嗯嗯、嗯、嗯嗯嗯……啾唔唔唔」", "tou412_038", "空_夜空", "bgm39", null, "After Story", null, null], [106, "柊史", "「……嗯嗯」", null, "空_夜空", "bgm39", null, "After Story", null, null], [107, "憧子", "「嗯、嗯啪啊啊，哈啊，哈啊……怎么觉得你亲得比平时更激烈？」", "tou412_039", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [108, "柊史", "「那当然了。我现在可兴奋了」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [109, "憧子", "「嗯嗯，我也一样，火燎火燎的。最近彼此工作都忙，时间总是对不上……嗯嗯、啾，啾唔唔」", "tou412_040", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [110, "柊史", "「是啊」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [111, "憧子", "「但是结了婚，一起生活之后……至少就不会见不上面了吧」", "tou412_041", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "10h", "pose": "3"}, "After Story", null, null], [112, "柊史", "「没错。只要有你在家等着，我一定会准时下班直接冲回家的」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "10h", "pose": "3"}, "After Story", null, null], [113, "憧子", "「呵呵，谢谢你……嗯啾噜，啾，啾……嗯嗯、嗯嗯……接吻，好舒服……嗯啾唔」", "tou412_042", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [114, "柊史", "「嗯哈啊，哈啊……憧子，我今天可能，真停不下来了」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [115, "憧子", "「我也是……身体热得停不下来了」", "tou412_043", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "28h", "pose": "2"}, "After Story", null, null], [116, "憧子", "「啊……所以我有个要求」", "tou412_044", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [117, "柊史", "「啊？什么要求？」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [118, "憧子", "「那个……你要让我舒服」", "tou412_045", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [119, "柊史", "「……」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [120, "柊史", "「那，那个……呃，这怎么说呢……你，你的意思是，平时不舒服咯？」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [121, "憧子", "「不是不是。我不是那个意思，那个……我去查了一下……据说舒服的话更容易受孕」", "tou412_046", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "17h", "pose": "2"}, "After Story", null, null], [122, "憧子", "「并不是平时不舒服哦？只是，呃……那个……我的意思是，要怀着让我比平时更舒服的念头来做」", "tou412_047", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "06h", "pose": "2"}, "After Story", null, null], [123, "憧子", "「对不起，是不是让你误会了？那个，平时也很舒服的哦？我说真的……」", "tou412_048", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [124, "柊史", "「这，这样啊……那我就放心了」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "07h", "pose": "2"}, "After Story", null, null], [125, "憧子", "「话说……真是的，我到底在说些什么啊……又在讲这种羞耻的事情」", "tou412_049", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [126, "", "扭扭捏捏的憧子满脸通红。", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [127, "", "……啊，明明平时总是摆出一副大姐姐做派，这种时候羞答答的样子也好可爱啊。", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [128, "柊史", "「憧子，为了这点事就害臊可不行啊」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [129, "柊史", "「毕竟为了变得更舒服，我们等一下还要做更羞耻的事情」", null, "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [130, "憧子", "「啊，唔……嗯……那就，拜托你了」", "tou412_050", "画面_黒", "bgm39", {"char": "ch_effect", "dress": "デート服", "face": "34h", "pose": "2"}, "After Story", null, null], [131, "憧子", "「啊、讨厌……怎么把头顶到那种地方去啦」", "tou412_051", "空_夜空", "bgm39", null, "After Story", null, null], [132, "柊史", "「难为情吗？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [133, "憧子", "「这个嘛，呃……如果我说难为情，你会停下吗？」", "tou412_052", "空_夜空", "bgm39", null, "After Story", null, null], [134, "柊史", "「不会。因为我是为了让你舒服才这么做的」", null, "空_夜空", "bgm39", null, "After Story", null, null], [135, "憧子", "「可是……可是……哈啊，哈啊……嗯、嗯唔唔唔……这种事还是头一回……嗯嗯」", "tou412_053", "空_夜空", "bgm39", null, "After Story", null, null], [136, "柊史", "「是这样吗？初体验的时候我不是也舔过吗？为了插得更顺畅一些」", null, "空_夜空", "bgm39", null, "After Story", null, null], [137, "憧子", "「那、那时候……因为我是背对着你的……可现在是面对面，脸什么的都被你瞧见了啦」", "tou412_054", "空_夜空", "bgm39", null, "After Story", null, null], [138, "柊史", "「可是……你现在心跳得很快吧？这种心跳感，你会讨厌吗？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [139, "憧子", "「这……唔唔、唔唔唔唔……」", "tou412_055", "空_夜空", "bgm39", null, "After Story", null, null], [140, "", "胯间就在眼前，而再远一点就是憧子的脸庞。", null, "空_夜空", "bgm39", null, "After Story", null, null], [141, "", "我轮番注视着她的这两个部位。", null, "空_夜空", "bgm39", null, "After Story", null, null], [142, "", "我还没有开始舔。可是憧子的内裤好像已经开始有点湿了。", null, "空_夜空", "bgm39", null, "After Story", null, null], [143, "柊史", "「这里……开始湿了。开始黏糊起来了啊」", null, "空_夜空", "bgm39", null, "After Story", null, null], [144, "憧子", "「哈啊，哈啊……嗯、嗯嗯……还不是因为你一直盯着看……哈啊，啊哈，哈啊，哈啊」", "tou412_056", "空_夜空", "bgm39", null, "After Story", null, null], [145, "柊史", "「看啊，渐渐变得透明了。你下流的那个部位，已经可以透过内裤看到了」", null, "空_夜空", "bgm39", null, "After Story", null, null], [146, "憧子", "「嗯嗯、哈、哈啊，哈啊……嗯嗯」", "tou412_057", "空_夜空", "bgm39", null, "After Story", null, null], [147, "柊史", "「光是被我看着就湿成这样……太厉害了。我看用不着更舒服了，现在这样应该就能马上怀上了吧？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [148, "憧子", "「哎？是、是这样吗？已经湿成那样了吗……？」", "tou412_058", "空_夜空", "bgm39", null, "After Story", null, null], [149, "柊史", "「要说真有多湿也不至于……反正应该有比平时湿得更快吧」", null, "空_夜空", "bgm39", null, "After Story", null, null], [150, "憧子", "「那、那么…你就必须让我更舒服才行。哈啊，哈啊，哈啊……再来……再来……」", "tou412_059", "空_夜空", "bgm39", null, "After Story", null, null], [151, "柊史", "「……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [152, "", "憧子的肌肤渐渐潮红，内裤也贴到了肉上。", null, "空_夜空", "bgm39", null, "After Story", null, null], [153, "", "连红色充血的阴核好像都透出来了。", null, "空_夜空", "bgm39", null, "After Story", null, null], [154, "柊史", "「哈啊……哈啊，哈啊……哈啊啊……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [155, "憧子", "「小柊……你喘得很厉害哦」", "tou412_060", "空_夜空", "bgm39", null, "After Story", null, null], [156, "柊史", "「对不起，可是……哈啊啊……哈啊……哈啊……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [157, "憧子", "「啊，啊，嗯嗯……哈啊，哈啊，呼出的气喷到上面……啊，啊，啊……好痒啊」", "tou412_061", "空_夜空", "bgm39", null, "After Story", null, null], [158, "柊史", "「应该不止是痒吧？毕竟你看，又更加湿了」", null, "空_夜空", "bgm39", null, "After Story", null, null], [159, "憧子", "「啊、啊啊啊……你盯得那么用力的话，嗯嗯、啊啊……哈、哈啊，哈啊，哈啊……我、我说，你就光看着吗？」", "tou412_062", "空_夜空", "bgm39", null, "After Story", null, null], [160, "柊史", "「光是看着就够湿了。你现在很兴奋吧？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [161, "憧子", "「那确实……嗯嗯……我心跳得很快……哈啊，哈啊……」", "tou412_063", "空_夜空", "bgm39", null, "After Story", null, null], [162, "", "憧子虽然羞得满脸通红，屁股却在不断颤抖。", null, "空_夜空", "bgm39", null, "After Story", null, null], [163, "", "简直就像在拼命勾引我，让我赶紧对她加以刺激。", null, "空_夜空", "bgm39", null, "After Story", null, null], [164, "", "更要命的是那种扑鼻而来的浓密的雌性气味。", null, "空_夜空", "bgm39", null, "After Story", null, null], [165, "", "就像被那种气味深深吸引住的飞虫一样，我往那里舔了上去。", null, "空_夜空", "bgm39", null, "After Story", null, null], [166, "柊史", "「嗯嗯，滋溜……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [167, "憧子", "「嗯嗯——！嗯啊、哈、哈啊，哈啊……嗯嗯、嗯唔唔……啊、哈、哈、嗯嗯嗯」", "tou412_064", "空_夜空", "bgm39", null, "After Story", null, null], [168, "憧子", "「讨厌，等一下。这样隔着内裤舔的话——嗯嗯」", "tou412_065", "空_夜空", "bgm39", null, "After Story", null, null], [169, "柊史", "「没事的。就算我不舔，内裤也已经湿透了。滋溜……滋溜滋溜」", null, "空_夜空", "bgm39", null, "After Story", null, null], [170, "憧子", "「嗯啊、嗯啊、啊啊啊啊————嗯嗯嗯……哈、哈、有这么夸张？已经全都湿透了？」", "tou412_066", "空_夜空", "bgm39", null, "After Story", null, null], [171, "柊史", "「是的，湿透了。你看，我这样一弄……啾，啾，啾嗞嗞嗞」", null, "空_夜空", "bgm39", null, "After Story", null, null], [172, "憧子", "「嗯啊啊？！啊、啊、啊啊啊……？！哈啊，啊哈，啊啊啊啊啊啊啊啊——！」", "tou412_067", "空_夜空", "bgm39", null, "After Story", null, null], [173, "", "憧子的粘液隔着内裤在我的口中扩散开来。", null, "空_夜空", "bgm39", null, "After Story", null, null], [174, "", "有点酸酸的，咸咸的。可能混了今天逛了一整天的汗味在里面。", null, "空_夜空", "bgm39", null, "After Story", null, null], [175, "柊史", "「啾噜、啾噜噜」", null, "空_夜空", "bgm39", null, "After Story", null, null], [176, "", "我为了细品那股味道，更用力地吸吮起性器来。", null, "空_夜空", "bgm39", null, "After Story", null, null], [177, "", "汁水被我强行吸走，发出下流的声响。", null, "空_夜空", "bgm39", null, "After Story", null, null], [178, "柊史", "「听到了吗？都发出这种声响了，你看淌得多厉害」", null, "空_夜空", "bgm39", null, "After Story", null, null], [179, "憧子", "「嗯啊，嗯啊啊啊啊啊……这，这么夸张，这不会是你口水的声音吧？嗯啊、嗯嗯、啊啊啊啊啊——啊」", "tou412_068", "空_夜空", "bgm39", null, "After Story", null, null], [180, "柊史", "「不是的。你的这里就是有这么湿。啾唔唔唔唔……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [181, "憧子", "「嗯嗯嗯呀……咕唔唔……啊，啊……啊啊——啊啊啊啊……声音，又响起来了……嗯啊、嗯啊、啊、嗯嗯嗯……」", "tou412_069", "空_夜空", "bgm39", null, "After Story", null, null], [182, "柊史", "「憧子，你都发出这种声音了，感觉一定很爽吧？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [183, "憧子", "「啊、嗯嗯、哈啊，哈啊……嗯，舒服……啊，啊，啊，被舔得，很爽……嗯嗯」", "tou412_070", "空_夜空", "bgm39", null, "After Story", null, null], [184, "柊史", "「……你自己也很清楚吧？你现在到底有多湿，啾噜噜」", null, "空_夜空", "bgm39", null, "After Story", null, null], [185, "憧子", "「嗯嗯嗯、啊、啊、啊……嗯嗯啊啊、啊、我，我知道，我都知道了，所以别再弄出那种声音了，嗯嗯……好难为情」", "tou412_071", "空_夜空", "bgm39", null, "After Story", null, null], [186, "憧子", "「而且……嗯嗯、内裤弄得这么湿……很麻烦的」", "tou412_072", "空_夜空", "bgm39", null, "After Story", null, null], [187, "柊史", "「没事的。反正放着不管就会干掉的。我今天就打算一直干到它晾干为止」", null, "空_夜空", "bgm39", null, "After Story", null, null], [188, "憧子", "「可是……嗯嗯，嗯啊、嗯啊……哈啊，哈啊，嗯、嗯嗯嗯嗯唔唔唔——！」", "tou412_073", "空_夜空", "bgm39", null, "After Story", null, null], [189, "柊史", "「穿着的话可没机会让它晾干。把它脱掉吧」", null, "空_夜空", "bgm39", null, "After Story", null, null], [190, "", "还没得到回应，我就把手搭在内裤上，慢慢将它脱了下来。", null, "空_夜空", "bgm39", null, "After Story", null, null], [191, "憧子", "「啊、啊啊啊……啊啊……哈啊，哈啊，哈啊，哈啊……被脱掉了」", "tou412_074", "空_夜空", "bgm39", null, "After Story", null, null], [192, "柊史", "「好湿……你的这个地方，好美」", null, "空_夜空", "bgm39", null, "After Story", null, null], [193, "憧子", "「哈啊……哈啊……哈啊，哈啊，哈啊，哈啊，被看光了……我湿漉漉的小穴，被这么近距离地看光了……啊啊啊啊啊……」", "tou412_075", "空_夜空", "bgm39", null, "After Story", null, null], [194, "", "我把脸凑得极近，近到都能看到憧子的穴内深处了。", null, "空_夜空", "bgm39", null, "After Story", null, null], [195, "", "雌性的气味越发强烈，粘稠的爱液也不断流淌而出，止都止不住。", null, "空_夜空", "bgm39", null, "After Story", null, null], [196, "憧子", "「呀、啊啊……脸好近啊……哈啊，哈啊，嗯嗯嗯」", "tou412_076", "空_夜空", "bgm39", null, "After Story", null, null], [197, "柊史", "「之前也是这么近的哦。不靠近怎么舔得到嘛」", null, "空_夜空", "bgm39", null, "After Story", null, null], [198, "憧子", "「唔、唔唔唔……哈啊，哈啊……对啊……啊真是的，为什么那个时候，我会同意你做这么羞耻的事情啊……哈啊，哈啊」", "tou412_077", "空_夜空", "bgm39", null, "After Story", null, null], [199, "柊史", "「但你并不讨厌这样吧？你反而……还想索求更多快感对吧？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [200, "憧子", "「这，这个嘛……嗯嗯、唔唔唔……真是的，你老是想让我说些害臊的话」", "tou412_078", "空_夜空", "bgm39", null, "After Story", null, null], [201, "", "憧子的声音听起来很惆怅。", null, "空_夜空", "bgm39", null, "After Story", null, null], [202, "", "但是，我眼中的性器是不会说谎的。", null, "空_夜空", "bgm39", null, "After Story", null, null], [203, "", "粉色的肉褶不断抽动收缩，渴望着更强烈的刺激。", null, "空_夜空", "bgm39", null, "After Story", null, null], [204, "", "明明朝着天花板方向，小穴中还是在不断冒出粘乎乎的透明液体。", null, "空_夜空", "bgm39", null, "After Story", null, null], [205, "柊史", "「你明明就不讨厌，毕竟都这么粘稠泛滥了。看，粘得都牵丝了」", null, "空_夜空", "bgm39", null, "After Story", null, null], [206, "憧子", "「那是因为……嗯啊啊啊啊啊啊……哈啊，哈啊，啊啊啊……」", "tou412_079", "空_夜空", "bgm39", null, "After Story", null, null], [207, "柊史", "「滋噜……滋啾滋啾……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [208, "", "我把舌头伸向冒出的粘液，感受它的触感和味道。", null, "空_夜空", "bgm39", null, "After Story", null, null], [209, "", "酸味好像比刚才要淡了。不过粘稠度有所提升……那汁液是真的很粘稠。", null, "空_夜空", "bgm39", null, "After Story", null, null], [210, "柊史", "「嗯，啾噜……嗯，嗯……啾唔唔唔唔」", null, "空_夜空", "bgm39", null, "After Story", null, null], [211, "", "这味道的变化特别有意思，勾起了我进一步确认的兴趣。", null, "空_夜空", "bgm39", null, "After Story", null, null], [212, "", "这次我直接怼着憧子湿哒哒的小穴吸了起来。", null, "空_夜空", "bgm39", null, "After Story", null, null], [213, "憧子", "「嗯呀？！嗯、嗯、嗯嗯咿咿————！不行……啊，啊，那样，不行啦，那里，亲住那里的话……啊、啊、啊」", "tou412_080", "空_夜空", "bgm39", null, "After Story", null, null], [214, "柊史", "「好像变得更湿了啊……滋溜滋溜，啾噗噗」", null, "空_夜空", "bgm39", null, "After Story", null, null], [215, "憧子", "「嗯啊啊啊啊——啊啊——啊、啊、啊、不要，不要啊……啊，啊，啊，啊……嗯嗯——」", "tou412_081", "空_夜空", "bgm39", null, "After Story", null, null], [216, "柊史", "「你最喜欢阴核被弄了呢」", null, "空_夜空", "bgm39", null, "After Story", null, null], [217, "憧子", "「呀啊、啊、等等……嗯嗯、啊啊啊啊啊——！不行，不行！」", "tou412_082", "空_夜空", "bgm39", null, "After Story", null, null], [218, "", "憧子不断摇晃身子，却并没有要逃离我舌尖的意思。", null, "空_夜空", "bgm39", null, "After Story", null, null], [219, "", "她反而像是为了获得更高的快感而晃动屁股，试图把胯间往我的头上顶。", null, "空_夜空", "bgm39", null, "After Story", null, null], [220, "憧子", "「嗯、呀咿咿！哈、哈啊，哈啊，哈啊，哈啊，哈啊……那里真的……啊，啊，啊，啊，阴核好怪，感觉不对劲啊……嗯——」", "tou412_083", "空_夜空", "bgm39", null, "After Story", null, null], [221, "柊史", "「没有不对劲。这才是正常的反应哦。而且我也很高兴……嗯，滋溜滋溜………啾唔唔」", null, "空_夜空", "bgm39", null, "After Story", null, null], [222, "", "我的舌头伸向憧子淌粘液的地方的不远处。", null, "空_夜空", "bgm39", null, "After Story", null, null], [223, "", "然后用舌尖舔舐、顶弄露出的敏感突起，然后用近似激吻的方式吸吮它。", null, "空_夜空", "bgm39", null, "After Story", null, null], [224, "", "憧子的身体瞬间就蹦了起来。", null, "空_夜空", "bgm39", null, "After Story", null, null], [225, "憧子", "「呀啊？！啊、那里，好麻……真的好麻……啊，啊——啊啊————不行不行，嗯、嗯嗯啊啊啊啊啊」", "tou412_084", "空_夜空", "bgm39", null, "After Story", null, null], [226, "", "憧子挣扎着合起双腿，似乎无法抵御这种刺激。", null, "空_夜空", "bgm39", null, "After Story", null, null], [227, "", "她用柔软的大腿夹住我的脑袋，拼命地挣扎着。", null, "空_夜空", "bgm39", null, "After Story", null, null], [228, "", "可我并没有停下。反反复复地舔舐着已经充血到通红的阴核，对着它又亲又吮。", null, "空_夜空", "bgm39", null, "After Story", null, null], [229, "憧子", "「啊、啊、嗯啊，嗯啊，嗯嗯啊啊啊啊……哈啊，哈啊，身体感觉不太对劲……不，不光是身体，脑袋也……」", "tou412_085", "空_夜空", "bgm39", null, "After Story", null, null], [230, "柊史", "「具体是怎样个不对劲法？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [231, "憧子", "「哎？啊，哈啊……哈啊……脑袋一片空白什么都没法想……哈啊，哈啊，而且像触电一样」", "tou412_086", "空_夜空", "bgm39", null, "After Story", null, null], [232, "憧子", "「哈啊，哈啊，哈啊啊啊……停不下来了，好舒服，粘乎乎的停不下来了……哈、哈啊，哈啊」", "tou412_087", "空_夜空", "bgm39", null, "After Story", null, null], [233, "柊史", "「真的……哇，已经泛滥成灾了……」", null, "空_夜空", "bgm39", null, "After Story", null, null], [234, "", "在我舔舐阴核的过程中，憧子的爱液也在流个没完。", null, "空_夜空", "bgm39", null, "After Story", null, null], [235, "", "不仅流个没完，流淌的量还越来越多……这样下去的话，我搞不好要淹死在这爱液里。", null, "空_夜空", "bgm39", null, "After Story", null, null], [236, "柊史", "「我帮你稍微清理一下……嗯啾……嗯嗯，滋溜滋溜，啾噜噜噜」", null, "空_夜空", "bgm39", null, "After Story", null, null], [237, "憧子", "「咿？！嗯啊、嗯啊、哈、哈咿——！啊，啊，怎么这样，啊、啊啊啊啊啊——啊啊啊啊啊……！」", "tou412_088", "空_夜空", "bgm39", null, "After Story", null, null], [238, "", "粘膜轻轻吸上了舌头和嘴唇。", null, "空_夜空", "bgm39", null, "After Story", null, null], [239, "", "虽说吸得没那么用力，但这感觉就像是在跟粘膜深吻一样，让人欲罢不能。", null, "空_夜空", "bgm39", null, "After Story", null, null], [240, "憧子", "「嗯啊啊啊啊啊——啊啊啊、啊，啊，呀咿……哈咿……嗯啊，嗯啊，嗯啊——啊啊啊啊！」", "tou412_089", "空_夜空", "bgm39", null, "After Story", null, null], [241, "柊史", "「你的声音好大。快感就这么强烈吗？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [242, "憧子", "「啊、嗯……嗯嗯唔唔唔……！嗯啊，嗯啊，嗯啊，嗯啊啊啊————啊啊啊……」", "tou412_090", "空_夜空", "bgm39", null, "After Story", null, null], [243, "柊史", "「你不用那样压低声音。毕竟这里就是那种旅馆。而且你的愿望就是被我伺候舒服吧？啾唔唔唔唔」", null, "空_夜空", "bgm39", null, "After Story", null, null], [244, "憧子", "「话、话是这么说……嗯啊，嗯啊，嗯啊啊啊——啊啊……不行不行，哈啊，哈啊，哈啊，哈啊，哈啊……现在真不能吸」", "tou412_091", "空_夜空", "bgm39", null, "After Story", null, null], [245, "柊史", "「滋溜滋溜……为什么不能吸？你看起来明明很舒服啊」", null, "空_夜空", "bgm39", null, "After Story", null, null], [246, "憧子", "「因为……你吸得那么用力……啊、啊、啊、啊身体都麻了……啊、啊、啊，好舒服，要爽过头了啦……」", "tou412_092", "空_夜空", "bgm39", null, "After Story", null, null], [247, "柊史", "「但舒服的话不是更容易受孕吗？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [248, "憧子", "「对、对啊……我得忍住……可是，可是……嗯嗯嗯、嗯啊，嗯啊啊啊……哈啊，哈啊，哈啊，哈啊哈啊哈啊哈，嗯嗯嗯嗯嗯————」", "tou412_093", "空_夜空", "bgm39", null, "After Story", null, null], [249, "", "憧子试图压抑住自己变快的呼吸和快感。", null, "空_夜空", "bgm39", null, "After Story", null, null], [250, "", "但我没有减弱舌头的力道。", null, "空_夜空", "bgm39", null, "After Story", null, null], [251, "柊史", "「嗯、滋噜滋噜……滋噜，啾，啾，啾噜噜噜——」", null, "空_夜空", "bgm39", null, "After Story", null, null], [252, "", "我用一如既往的力道……不，我更加用力地吸住阴核，加以刺激。", null, "空_夜空", "bgm39", null, "After Story", null, null], [253, "憧子", "「唔唔啊啊啊……啊啊啊？！呀咿，呀咿，嗯嗯、嗯嗯嗯……嗯啊啊啊！啊啊啊啊啊嗯……！」", "tou412_094", "空_夜空", "bgm39", null, "After Story", null, null], [254, "憧子", "「果、果然不行……不行不行，这叫人怎么忍啊……哈啊啊，哈、哈、哈啊哈啊哈啊……嗯嗯！」", "tou412_095", "空_夜空", "bgm39", null, "After Story", null, null], [255, "", "呻吟声犹如叫喊一般的憧子用手脚使劲做出抵抗。", null, "空_夜空", "bgm39", null, "After Story", null, null], [256, "", "即便如此我也没有停下，就像把阴核当成了开关按钮一样，用舌尖用力顶压。", null, "空_夜空", "bgm39", null, "After Story", null, null], [257, "憧子", "「呀啊啊啊——！嗯——小，小柊……嗯，嗯————！不行，真的不对劲，我要疯了……啊————！」", "tou412_096", "空_夜空", "bgm39", null, "After Story", null, null], [258, "柊史", "「可以哦，你就直接高潮吧」", null, "空_夜空", "bgm39", null, "After Story", null, null], [259, "憧子", "「啊、啊、啊啊——啊啊……好舒服……啊，啊，啊，不能，这么舒服……不行不行，真的好爽……啊啊，饶了我，饶了我吧……」", "tou412_097", "空_夜空", "bgm39", null, "After Story", null, null], [260, "", "大腿夹脑袋的力道越发强烈。", null, "空_夜空", "bgm39", null, "After Story", null, null], [261, "", "与此同时，腿上的剧烈震动似乎也传导到了我的头上。", null, "空_夜空", "bgm39", null, "After Story", null, null], [262, "憧子", "「住手……啊，啊，啊————不行，舒服，爽死……了……嗯啊，嗯啊——」", "tou412_098", "空_夜空", "bgm39", null, "After Story", null, null], [263, "憧子", "「啊、啊、啊——去了去了，嗯嗯……去了啊啊啊啊啊————唔唔唔！」", "tou412_099", "空_夜空", "bgm39", null, "After Story", null, null], [264, "", "憧子的全身剧烈地痉挛起来。", null, "画面_白", "bgm39", null, "After Story", null, null], [265, "", "而把脑袋埋在胯间的我，也被透明的粘液喷了一脸。", null, "画面_白", "bgm39", null, "After Story", null, null], [266, "憧子", "「啊、呀、啊——啊——停不下来，停不下来了……对不起，可是，可是，啊、啊、啊啊啊啊啊啊啊……」", "tou412_100", "画面_白", "bgm39", null, "After Story", null, null], [267, "柊史", "「唔噗、嗯、嗯嗯……嗯啾噜，啾噜噜噜，啾，啾……啾唔唔唔唔」", null, "画面_白", "bgm39", null, "After Story", null, null], [268, "", "因为高潮的缘故，我的脑袋被她的手死死按住。", null, "画面_白", "bgm39", null, "After Story", null, null], [269, "", "我也没有勉强去反抗，而是顺势舔起了液体，努力吸吮着将它喝了个精光。", null, "画面_白", "bgm39", null, "After Story", null, null], [270, "憧子", "「哈啊——啊啊，哈啊——啊啊……不行，不行……现在亲上去的话……啊、啊、啊、脑袋里都要变成浆糊了啦」", "tou412_101", "画面_白", "bgm39", null, "After Story", null, null], [271, "柊史", "「憧子……嗯，憧子……嗯，好咸……嗯啾噜噜」", null, "画面_白", "bgm39", null, "After Story", null, null], [272, "憧子", "「啊，啊，啊————等下等下，我又要……啊、啊、啊、又要去了，又要去了啦……！」", "tou412_102", "画面_白", "bgm39", null, "After Story", null, null], [273, "憧子", "「不要……停，快停下……哈啊，哈啊啊啊啊……不行，不行……真的停不下来，停不下来了……啊、啊、啊、啊——」", "tou412_103", "画面_白", "bgm39", null, "After Story", null, null], [274, "憧子", "「啊啊啊啊啊啊啊啊————！」", "tou412_104", "画面_白", "bgm39", null, "After Story", null, null], [275, "憧子", "「啊，啊，啊————我都说不行了……啊啊，快住手，不行，啊——啊——我停不下来了」", "tou412_105", "画面_白", "bgm39", null, "After Story", null, null], [276, "", "粘液再度激烈地喷出。", null, "画面_白", "bgm39", null, "After Story", null, null], [277, "", "我拼命接住在嘴边喷洒的水流，不断吞咽。", null, "画面_白", "bgm39", null, "After Story", null, null], [278, "柊史", "「嗯唔，嗯、嗯嗯……嗯啾噜，嗯嗯嗯」", null, "画面_白", "bgm39", null, "After Story", null, null], [279, "憧子", "「啊，啊，啊，啊啊啊啊，又、又来！要、要把人整疯了啦……哈啊，哈啊，嗯、嗯嗯咿咿！」", "tou412_106", "画面_白", "bgm39", null, "After Story", null, null], [280, "", "憧子的身体微微颤抖，粘液喷薄而出。", null, "画面_白", "bgm39", null, "After Story", null, null], [281, "憧子", "「哈啊，哈啊，嗯嗯、嗯嗯嗯嗯——噶、哈啊，哈啊，哈啊，啊、啊——不能再舔了」", "tou412_107", "画面_白", "bgm39", null, "After Story", null, null], [282, "柊史", "「憧、憧子，你松一下腿……滋噜滋噜」", null, "画面_白", "bgm39", null, "After Story", null, null], [283, "憧子", "「啊，啊啊……嗯，对不起……哈啊，哈啊，哈啊，哈啊啊……」", "tou412_108", "画面_白", "bgm39", null, "After Story", null, null], [284, "", "憧子松开手脚后，我才总算停止了对胯间的唇舌攻势。", null, "画面_白", "bgm39", null, "After Story", null, null], [285, "憧子", "「哈、哈啊——哈啊——哈啊——已经舔得够多了啦……啊、嗯嗯嗯、我都说了多少遍不行了，哈啊——哈啊——」", "tou412_109", "画面_白", "bgm39", null, "After Story", null, null], [286, "柊史", "「因为你的大腿一直夹着我不放啊」", null, "画面_白", "bgm39", null, "After Story", null, null], [287, "憧子", "「那还不是因为你让我舒服过头了，哈啊——哈啊——」", "tou412_110", "画面_白", "bgm39", null, "After Story", null, null], [288, "", "憧子的胯间湿得一塌糊涂。", null, "画面_白", "bgm39", null, "After Story", null, null], [289, "", "对着我的脸喷溅的粘液，也溅到了憧子自己身上。", null, "画面_白", "bgm39", null, "After Story", null, null], [290, "憧子", "「啊、哈啊——哈啊——啊啊，有点使不上劲……嗯、嗯嗯」", "tou412_111", "画面_白", "bgm39", null, "After Story", null, null], [291, "柊史", "「你真可爱……真就这么爽吗？」", null, "画面_白", "bgm39", null, "After Story", null, null], [292, "憧子", "「嗯，嗯……啊、哈啊——哈啊——眼前都变成了白茫茫的一片……哈、哈啊啊啊……」", "tou412_112", "画面_白", "bgm39", null, "After Story", null, null], [293, "柊史", "「……憧子……」", null, "画面_白", "bgm39", null, "After Story", null, null], [294, "憧子", "「哎……什么？」", "tou412_113", "画面_白", "bgm39", null, "After Story", null, null], [295, "柊史", "「以防万一，我看你最好还是再湿一点比较好哦」", null, "画面_白", "bgm39", null, "After Story", null, null], [296, "憧子", "「……哎，哎哎？你的意思是……你、你来真的？」", "tou412_114", "画面_白", "bgm39", null, "After Story", null, null], [297, "", "憧子拖着烂泥般的身体，一脸吃惊地抬头看我。", null, "画面_白", "bgm39", null, "After Story", null, null], [298, "", "在她回答之前，我把脸凑向胯间，又把舌头缠了上去。", null, "画面_白", "bgm39", null, "After Story", null, null], [299, "憧子", "「咿咕？！嗯，嗯、嗯啊啊啊啊啊啊，行，行了，已经够了、够湿了啦……唔唔啊啊啊，啊、啊、啊啊」", "tou412_115", "画面_白", "bgm39", null, "After Story", null, null], [300, "憧子", "「啊啊，真是的，又来这套……嗯、嗯嗯——！嗯嗯——啊啊啊啊啊」", "tou412_116", "画面_白", "bgm39", null, "After Story", null, null], [301, "柊史", "「滋溜滋溜滋溜……啾，啾噜噜」", null, "画面_白", "bgm39", null, "After Story", null, null], [302, "憧子", "「啊，啊——这，这，现在真的，敏感过头了……嗯啊！啊！哈啊！哈啊啊嗯！」", "tou412_117", "画面_白", "bgm39", null, "After Story", null, null], [303, "柊史", "「啊啊……你的这里真的好好吃，滋溜滋溜滋溜滋溜」", null, "画面_白", "bgm39", null, "After Story", null, null], [304, "憧子", "「啊，啊，啊，啊，真的不行……嗯嗯嗯、啊啊啊！去了……啊，啊……又要去了啦，啊、啊、啊、啊啊啊啊——！」", "tou412_118", "画面_白", "bgm39", null, "After Story", null, null], [305, "", "咕啾咕啾……随着我舌头的动作，水声自然响起。", null, "画面_白", "bgm39", null, "After Story", null, null], [306, "", "在经过了两次高潮后，憧子已经湿得咕叽作响了。", null, "画面_白", "bgm39", null, "After Story", null, null], [307, "", "我舔着阴核，然后把舌头深入其中用力吸吮，就像要把小穴吃掉一样。", null, "画面_白", "bgm39", null, "After Story", null, null], [308, "憧子", "「嗯呀啊啊啊啊……不行，这样不行……求你了，啊，啊，啊，我身上已经麻得不行了……嗯啊！」", "tou412_119", "画面_白", "bgm39", null, "After Story", null, null], [309, "憧子", "「啊，啊，啊，啊好厉害……这样的话，脑子会疯掉的……呀，啊啊……啊，啊，啊，啊，舔得好棒……嗯、嗯嗯啊」", "tou412_120", "画面_白", "bgm39", null, "After Story", null, null], [310, "柊史", "「向我展示你迷乱的一面吧……被我的舌头弄疯吧……嗯，啾噜噜噜噜」", null, "画面_白", "bgm39", null, "After Story", null, null], [311, "憧子", "「呀，嗯嗯嗯……嗯嗯咿咿咿咿————咿咿……」", "tou412_121", "画面_白", "bgm39", null, "After Story", null, null], [312, "", "憧子好像连眼睛都失了焦，她的小嘴一张一闭地索求着氧气，口水从中滴落的样子看起来放荡至极。", null, "画面_白", "bgm39", null, "After Story", null, null], [313, "", "紧接着，炙热粘稠的水流第三次朝我袭来。", null, "画面_白", "bgm39", null, "After Story", null, null], [314, "憧子", "「哈咿，哈啊啊啊……啊，啊，啊……好厉害，融化了……小穴都融化了……啊啊啊，被舔化了，嗯嗯嗯……」", "tou412_122", "画面_白", "bgm39", null, "After Story", null, null], [315, "", "……看她爽成这样让我特别开心，弄得我想再多喝一点爱液……舌头想都没想就动了起来。", null, "画面_白", "bgm39", null, "After Story", null, null], [316, "柊史", "「憧子，你这边简直一发不可收拾啊。我得再帮你清理干净」", null, "画面_白", "bgm39", null, "After Story", null, null], [317, "憧子", "「哎？啊，又来？啊，啊，啊，等等，不能再来了，真的不行了……啊、啊啊、都说不行了…哈、哈、哈啊啊啊……！」", "tou412_123", "画面_白", "bgm39", null, "After Story", null, null], [318, "", "我不管不顾地把头埋进憧子的胯间。", null, "画面_白", "bgm39", null, "After Story", null, null], [319, "", "那之后又过了多久呢？", null, "空_夜空", "bgm39", null, "After Story", null, null], [320, "", "我一直把脸埋在憧子身上，久到我感觉嘴唇皮都要泡胀了。", null, "空_夜空", "bgm39", null, "After Story", null, null], [321, "", "而在仔细地、认真地清理完湿漉漉的小穴之后……我这才发觉，憧子的身体已经完全脱力了。", null, "空_夜空", "bgm39", null, "After Story", null, null], [322, "憧子", "「哈咿、哈咿、啊啊啊啊——别再来了，我都要被你弄死了……爽过头了，在受孕之前小穴就要坏掉了啦……」", "tou412_124", "空_夜空", "bgm39", null, "After Story", null, null], [323, "柊史", "「憧子，你这下舒服了吗？」", null, "空_夜空", "bgm39", null, "After Story", null, null], [324, "憧子", "「舒服了。很久之前就舒服够了，舒服过头了……哈啊，哈啊，哈啊，哈啊……」", "tou412_125", "空_夜空", "bgm39", null, "After Story", null, null], [325, "憧子", "「所以拜托你……我想要……好想要，哈啊，哈啊……在小穴坏掉之前，快点……嗯嗯、哈啊——哈啊——」", "tou412_126", "空_夜空", "bgm39", null, "After Story", null, null], [326, "柊史", "「我明白了」", null, "空_夜空", "bgm39", null, "After Story", null, null], [327, "柊史", "「这样就行了吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [328, "憧子", "「嗯……嗯。直接插进来吧……哈啊……哈啊……」", "tou412_127", "画面_黒", "bgm26", null, "After Story", null, null], [329, "憧子", "「这样一来，精子好像会更容易进到深处，也就更容易受孕……所以直接来吧，哈啊，哈啊」", "tou412_128", "画面_黒", "bgm26", null, "After Story", null, null], [330, "柊史", "「我明白了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [331, "", "憧子经历了好几次高潮，小穴潮吹个没完。", null, "画面_黒", "bgm26", null, "After Story", null, null], [332, "", "她的性器已经泛滥成灾，现在应该已经用不着爱抚了。", null, "画面_黒", "bgm26", null, "After Story", null, null], [333, "", "而我这边也……", null, "画面_黒", "bgm26", null, "After Story", null, null], [334, "", "……咕啾。", null, "画面_黒", "bgm26", null, "After Story", null, null], [335, "憧子", "「啊，嗯嗯……鸡鸡变得好烫，我能感觉得到……嗯嗯、感觉都要被烫伤了……」", "tou412_129", "画面_黒", "bgm26", null, "After Story", null, null], [336, "柊史", "「不光这样。看了这么久你的可爱模样，我也已经山洪爆发了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [337, "柊史", "「预射液流个没完，想插得不行」", null, "画面_黒", "bgm26", null, "After Story", null, null], [338, "憧子", "「嗯、唔唔，哈啊啊……那你还一直用舌头欺负我做什么，明明可以早点跟我说的呀……」", "tou412_130", "画面_黒", "bgm26", null, "After Story", null, null], [339, "柊史", "「因为你太可爱了，我怎么都停不下来」", null, "画面_黒", "bgm26", null, "After Story", null, null], [340, "憧子", "「真是的……嗯嗯……我明明早就准备好了……哈啊，哈啊……」", "tou412_131", "画面_黒", "bgm26", null, "After Story", null, null], [341, "柊史", "「我知道。毕竟都这么湿了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [342, "憧子", "「既然都知道了，还那样欺负我……下次换我来惩罚你欺负你了，做好觉悟吧」", "tou412_132", "画面_黒", "bgm26", null, "After Story", null, null], [343, "柊史", "「这倒是……让人心生期待啊。但是那个的话下次再说吧。现在我们要……来这个哦」", null, "画面_黒", "bgm26", null, "After Story", null, null], [344, "", "刚才我说了“泛滥成灾”这个词……而这个词现在已经无法形容憧子粘膜的湿润程度了。", null, "画面_黒", "bgm26", null, "After Story", null, null], [345, "", "阴茎的前端一摩擦阴部，就会响起粘稠的水声。", null, "画面_黒", "bgm26", null, "After Story", null, null], [346, "憧子", "「啊、嗯、嗯嗯……哈啊，哈啊，哈啊……嗯，嗯。啊，啊啊……快，快，快点快点——」", "tou412_133", "画面_黒", "bgm26", null, "After Story", null, null], [347, "", "——咕噗噗。", null, "画面_黒", "bgm26", null, "After Story", null, null], [348, "憧子", "「嗯嗯嗯……啊啊啊，啊——进来了……哈啊，哈啊，哈啊……嗯嗯！」", "tou412_134", "画面_黒", "bgm26", null, "After Story", null, null], [349, "柊史", "「唔……你的里面好紧……而且你这边才叫烫呢，简直烫死我了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [350, "憧子", "「哈啊，哈啊……这说明我有多舒服……唔唔嗯。我都热得受不了了你还一直舔……」", "tou412_135", "画面_黒", "bgm26", null, "After Story", null, null], [351, "憧子", "「那感觉可难受了你知道不……哈啊，哈啊……可是你却一次又一次地把我舔到高潮……啊、嗯啊，哈啊啊……嗯嗯」", "tou412_136", "画面_黒", "bgm26", null, "After Story", null, null], [352, "柊史", "「确实……我进去的时候你里面扭得厉害极了，就像遇上了什么天大的喜事」", null, "画面_黒", "bgm26", null, "After Story", null, null], [353, "憧子", "「不是像，哈、嗯嗯……我就是高兴啊。鸡鸡插进来……哈啊，哈啊，嗯嗯……啊啊，最深处终于充实了」", "tou412_137", "画面_黒", "bgm26", null, "After Story", null, null], [354, "", "憧子边说边扭腰，奋力将胯间顶向我的腰。", null, "画面_黒", "bgm26", null, "After Story", null, null], [355, "憧子", "「求你了，再插深一点……一直插到底……哈啊，哈啊，嗯嗯」", "tou412_138", "画面_黒", "bgm26", null, "After Story", null, null], [356, "柊史", "「这也是为了更容易受孕吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [357, "憧子", "「嗯，是啊……哈啊，哈啊……嗯、在最深处全部射出来，这样是最好的」", "tou412_139", "画面_黒", "bgm26", null, "After Story", null, null], [358, "憧子", "「所以你要在我的最深处射出来……把粘稠的精液一口气射进来，一直射到满出来为止……嗯嗯」", "tou412_140", "画面_黒", "bgm26", null, "After Story", null, null], [359, "憧子", "「这样我就原谅你刚才欺负我的事」", "tou412_141", "画面_黒", "bgm26", null, "After Story", null, null], [360, "柊史", "「……哎……你肯原谅我吗？那下次的惩罚怎么说？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [361, "憧子", "「下次不惩罚你了。我会用满满的福利代替惩罚」", "tou412_142", "画面_黒", "bgm26", null, "After Story", null, null], [362, "柊史", "「既然这样……那我动了哦」", null, "画面_黒", "bgm26", null, "After Story", null, null], [363, "憧子", "「好，好的，拜托你了……嗯嗯、嗯……啊、啊、啊……动起来了，我感觉到了……嗯嗯」", "tou412_143", "画面_黒", "bgm26", null, "After Story", null, null], [364, "憧子", "「啊，啊，啊，里面在摩擦……哈啊，哈啊，嗯、嗯嗯嗯」", "tou412_144", "画面_黒", "bgm26", null, "After Story", null, null], [365, "", "憧子的小穴里已经洪水横流。", null, "画面_黒", "bgm26", null, "After Story", null, null], [366, "", "我只不过稍微挺个腰，咕啾咕啾的水声就从结合部响起，刺激着我和憧子的耳膜。", null, "画面_黒", "bgm26", null, "After Story", null, null], [367, "憧子", "「嗯咿、啊、啊、啊……嗯、嗯嗯嗯，哈啊，哈啊，哈啊……嗯嗯嗯」", "tou412_145", "画面_黒", "bgm26", null, "After Story", null, null], [368, "柊史", "「这样动没问题吧？舒不舒服？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [369, "憧子", "「嗯啊，嗯啊啊……哈啊，哈啊……嗯嗯、嗯，很舒服哦。啊、啊……好像真的插得很深呢」", "tou412_146", "画面_黒", "bgm26", null, "After Story", null, null], [370, "憧子", "「嗯哈啊、啊、啊啊啊……从来，没这么深过……嗯、啊！啊！蹭到陌生的部位了……」", "tou412_147", "画面_黒", "bgm26", null, "After Story", null, null], [371, "", "憧子将我的阴茎没根吞入。", null, "画面_黒", "bgm26", null, "After Story", null, null], [372, "柊史", "「搞不好是子宫降下来了吧……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [373, "憧子", "「是吗？啊，可能真是这样……啊、啊、啊、反正很舒服，怎么都行了……啊啊！」", "tou412_148", "画面_黒", "bgm26", null, "After Story", null, null], [374, "", "磨蹭到陌生部位的触感……唔、啊啊、这样我好像也挺爽的。", null, "画面_黒", "bgm26", null, "After Story", null, null], [375, "憧子", "「咿嗯！啊，啊，啊，啊啊啊啊……哈啊，哈啊啊……被抚摸着。小穴里面，正在被棒棒抚摸呢……嗯啊啊」", "tou412_149", "画面_黒", "bgm26", null, "After Story", null, null], [376, "柊史", "「这边舒服吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [377, "憧子", "「嗯，嗯……啊啊嗯！啊嗯，啊嗯，嗯嗯……！磨蹭那里，好舒服……啊、啊、啊」", "tou412_150", "画面_黒", "bgm26", null, "After Story", null, null], [378, "柊史", "「我再摩擦看看其他地方」", null, "画面_黒", "bgm26", null, "After Story", null, null], [379, "憧子", "「嗯……都试试看好了……嗯、啊，啊……哈啊，哈啊，嗯、嗯嗯……」", "tou412_151", "画面_黒", "bgm26", null, "After Story", null, null], [380, "", "咕啾……咕啾……咕噗咕噗。在这样的声响之中，我慢慢调整腰的位置以及抽插角度，同时观察憧子的反应。", null, "画面_黒", "bgm26", null, "After Story", null, null], [381, "憧子", "「啊……啊……嗯、嗯嗯嗯……哈、啊！嗯、嗯啊，哈啊……哈啊……嗯嗯」", "tou412_152", "画面_黒", "bgm26", null, "After Story", null, null], [382, "", "憧子挺着腰肢，用肉褶摩擦阴茎的同时身子也微微颤抖着。", null, "画面_黒", "bgm26", null, "After Story", null, null], [383, "", "接着她发出惆怅的呻吟，使劲用指甲抠着我的脖子。", null, "画面_黒", "bgm26", null, "After Story", null, null], [384, "憧子", "「啊，啊，啊……嗯、啊……咕唔……哈啊，哈啊，哈啊……嗯，嗯嗯嗯……嗯」", "tou412_153", "画面_黒", "bgm26", null, "After Story", null, null], [385, "柊史", "「不怎么舒服吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [386, "憧子", "「嗯嗯、啊、哈啊，哈啊……没那回事，很舒服哦……哈啊，哈啊嗯」", "tou412_154", "画面_黒", "bgm26", null, "After Story", null, null], [387, "柊史", "「不过最里面好像是挺舒服的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [388, "", "于是我再次将阴茎顶进深处，几乎都要够到子宫口。", null, "画面_黒", "bgm26", null, "After Story", null, null], [389, "憧子", "「呀、啊、啊嗯、啊嗯、嗯嗯嗯嗯——啊啊啊、嗯啊、嗯啊、嗯嗯唔唔……」", "tou412_155", "画面_黒", "bgm26", null, "After Story", null, null], [390, "柊史", "「深一点的地方果然反应更好」", null, "画面_黒", "bgm26", null, "After Story", null, null], [391, "憧子", "「嗯、啊，哈啊，哈啊……深的地方好像确实舒服……哈啊，哈啊，啊啊、能不能再往深一点的地方摸摸……」", "tou412_156", "画面_黒", "bgm26", null, "After Story", null, null], [392, "柊史", "「我明白了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [393, "", "话虽如此，但深度基本已经到极限了……我把腰尽可能贴紧她的胯部，使劲晃动身体。", null, "画面_黒", "bgm26", null, "After Story", null, null], [394, "憧子", "「咿，啊嗯……嗯嗯、啊啊啊、哈啊……哈啊……哈啊……嗯嗯、嗯……嗯啊？！啊、啊、啊啊啊啊啊——啊啊啊！」", "tou412_157", "画面_黒", "bgm26", null, "After Story", null, null], [395, "", "我摆弄腰部反复蹭弄，憧子的身子忽然猛地一抽。", null, "画面_黒", "bgm26", null, "After Story", null, null], [396, "柊史", "「刚才有反应了呢。这里很舒服吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [397, "", "我为了确认刚才蹭到的部位，来回挺腰试探。", null, "画面_黒", "bgm26", null, "After Story", null, null], [398, "", "随着深处的滑溜粘膜被不断摩擦，憧子的呻吟声也越来越尖。", null, "画面_黒", "bgm26", null, "After Story", null, null], [399, "憧子", "「啊！啊、啊、啊……嗯、嗯唔唔唔唔……哈、哈啊、哈啊、嗯！嗯嗯！嗯嗯嗯！嗯啊、嗯啊、啊啊啊——」", "tou412_158", "画面_黒", "bgm26", null, "After Story", null, null], [400, "柊史", "「这里的反应果然是最好的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [401, "憧子", "「啊嗯、嗯嗯、嗯啊——嗯啊——那里那里、蹭到那里之后……好棒、好喜欢，那里好棒，啊、啊、啊啊啊！」", "tou412_159", "画面_黒", "bgm26", null, "After Story", null, null], [402, "", "随着憧子的喘息越发沉重，粘膜也扭动着攀上了阴茎，越缠越紧。", null, "画面_黒", "bgm26", null, "After Story", null, null], [403, "", "滚烫粘稠的粘膜紧紧裹住整根肉棒的感觉，实在是爽得难以言喻。", null, "画面_黒", "bgm26", null, "After Story", null, null], [404, "", "我就像是在憧子的肉穴里融化了一样……下腰真要使不上劲了……", null, "画面_黒", "bgm26", null, "After Story", null, null], [405, "憧子", "「好舒服……哈啊，哈啊，嗯嗯、啊，啊，啊啊啊……那里那里……太棒了……嗯、嗯、嗯嗯嗯啊啊」", "tou412_160", "画面_黒", "bgm26", null, "After Story", null, null], [406, "柊史", "「这样弄有那么爽吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [407, "憧子", "「嗯……舒服……鸡鸡正在抚摸着我的最深处，就是那些用手指玩弄或者用舌头舔时所触碰不到的部位」", "tou412_161", "画面_黒", "bgm26", null, "After Story", null, null], [408, "憧子", "「那样好舒服……啊，啊，啊啊啊……真的太棒了，嗯，嗯嗯嗯……哈啊，哈啊啊……嗯嗯嗯！」", "tou412_162", "画面_黒", "bgm26", null, "After Story", null, null], [409, "柊史", "「啊，啊，啊啊……我也很舒服。你蹭着我的前端，同时紧紧夹着肉棒……哈啊，哈啊……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [410, "柊史", "「憧子，你能夹得更紧一些吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [411, "憧子", "「哈啊，哈啊，哈啊……嗯唔唔……我也不知道啊，我会努力试试，不过这股舒服劲让我没办法好好发力……哈啊，哈啊……嗯、嗯嗯嗯」", "tou412_163", "画面_黒", "bgm26", null, "After Story", null, null], [412, "", "憧子的胯部一使劲，粘液的飞沫瞬间喷溅而出。", null, "画面_黒", "bgm26", null, "After Story", null, null], [413, "", "憧子的里面如我要求的那样紧紧收缩。", null, "画面_黒", "bgm26", null, "After Story", null, null], [414, "憧子", "「这、这样感觉如何？哈啊，哈啊，我有成功吗？舒服吗？」", "tou412_164", "画面_黒", "bgm26", null, "After Story", null, null], [415, "柊史", "「嗯，很舒服。又软，又热，又湿……啊啊……真的好舒服」", null, "画面_黒", "bgm26", null, "After Story", null, null], [416, "", "我就在这么紧致的小穴中，为了获得快感而贪婪地挺腰抽送。", null, "画面_黒", "bgm26", null, "After Story", null, null], [417, "憧子", "「啊、啊、啊、啊，啊，啊，啊……喜欢，好喜欢这样，啊，啊，啊，那里，好舒服好喜欢……嗯嗯」", "tou412_165", "画面_黒", "bgm26", null, "After Story", null, null], [418, "柊史", "「这里的反应真的很棒啊。这就像是你的开关一样。按下去之后……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [419, "憧子", "「啊，啊，啊啊啊……那里那里……啊，啊，啊，喜欢……那里被鸡鸡爱抚，我好喜欢……嗯啊、嗯啊、啊啊啊——啊啊啊」", "tou412_166", "画面_黒", "bgm26", null, "After Story", null, null], [420, "柊史", "「听，发出的叫声有多下流」", null, "画面_黒", "bgm26", null, "After Story", null, null], [421, "憧子", "「啊啊嗯、嗯嗯……啊、那里那里、哈、哈……那里，可能真的是我的开关」", "tou412_167", "画面_黒", "bgm26", null, "After Story", null, null], [422, "憧子", "「啊，啊，啊，啊，嗯啊啊啊啊！舒服过头了……我说，这样没问题吧？我的表情不会因为舒服过了头而变得很奇怪吧？哈啊，哈啊」", "tou412_168", "画面_黒", "bgm26", null, "After Story", null, null], [423, "柊史", "「没事的。憧子，你现在非常可爱」", null, "画面_黒", "bgm26", null, "After Story", null, null], [424, "憧子", "「哈、哈、嗯嗯嗯……唔啊啊！啊！啊！鸡鸡一下一下地摸着……哈啊，哈啊，嗯、嗯啊啊啊——啊啊啊啊」", "tou412_169", "画面_黒", "bgm26", null, "After Story", null, null], [425, "憧子", "「怎么办，啊、啊、啊，我好喜欢摸摸头……可我发现自己好像也很喜欢摸摸小穴……哈啊，哈啊，嗯嗯！」", "tou412_170", "画面_黒", "bgm26", null, "After Story", null, null], [426, "柊史", "「喜欢的话也没办法啊。那我就多摸几下吧」", null, "画面_黒", "bgm26", null, "After Story", null, null], [427, "憧子", "「嗯嗯——啊啊啊啊啊啊啊！啊咿、啊咿……我，我……啊、啊，好有感觉。感觉太强烈了……啊——啊啊啊——」", "tou412_171", "画面_黒", "bgm26", null, "After Story", null, null], [428, "", "憧子不但粘膜里面泛滥，连表情都越发浪荡。", null, "画面_黒", "bgm26", null, "After Story", null, null], [429, "", "她的感觉来得比平时更快，方式好像也更加猛烈。", null, "画面_黒", "bgm26", null, "After Story", null, null], [430, "", "这也是刚才长时间帮她口交的功劳吗？", null, "画面_黒", "bgm26", null, "After Story", null, null], [431, "憧子", "「啊、啊、啊啊啊……不行不行，我的表情肯定会变得很怪，啊、啊、啊、小穴太舒服了，我的表情绝对会变得很怪的……啊啊啊嗯」", "tou412_172", "画面_黒", "bgm26", null, "After Story", null, null], [432, "柊史", "「表情一点都不怪。又可爱又下流……太有魅力了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [433, "憧子", "「啊啊嗯、你这是在敷衍我……哈啊，哈啊，下流的表情不就是奇怪的表情吗？」", "tou412_173", "画面_黒", "bgm26", null, "After Story", null, null], [434, "柊史", "「那不一样。你的表情真的很可爱，我最喜欢了。我还想多看一点你下流的表情……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [435, "憧子", "「啊，啊，啊、嗯嗯嗯嗯嗯……哈啊，哈啊……啊，啊，啊，不行，明明不可以……啊，啊、要变了，要变成下流的表情了」", "tou412_174", "画面_黒", "bgm26", null, "After Story", null, null], [436, "", "我像野兽一样贪婪地在憧子体内掠食。", null, "画面_黒", "bgm26", null, "After Story", null, null], [437, "", "我为了够到最深处而用力扭腰挺送，肆意摩擦搅和着湿滑的粘膜。", null, "画面_黒", "bgm26", null, "After Story", null, null], [438, "憧子", "「那样，那样好棒……嗯嗯、啊啊啊啊、我，我真的变成淫荡的女孩了……啊，啊、啊啊……啊、啊、啊——」", "tou412_175", "画面_黒", "bgm26", null, "After Story", null, null], [439, "憧子", "「啊啊啊啊、又要变得更淫荡了……啊，啊，啊，啊、脑子里越来越淫荡了」", "tou412_176", "画面_黒", "bgm26", null, "After Story", null, null], [440, "柊史", "「我可是一直都很淫荡的。所以你也跟我一样怎么舒服怎么做吧，没事的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [441, "憧子", "「可是，你也要舒服才行，哈啊——哈啊——嗯嗯、啊，哈啊，哈啊，哈啊，我明明必须让精液咻地射出来才行」", "tou412_177", "画面_黒", "bgm26", null, "After Story", null, null], [442, "柊史", "「没问题的……我也真的很舒服，很快就要射了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [443, "憧子", "「真的吗？那就变得……变得更舒服一些，啊、啊、啊、然后在我的小穴里咻地射出来吧」", "tou412_178", "画面_黒", "bgm26", null, "After Story", null, null], [444, "柊史", "「嗯，我一定会射给你的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [445, "", "我一边伺候着憧子，一边挺腰抽送为射精做最后冲刺。", null, "画面_黒", "bgm26", null, "After Story", null, null], [446, "", "啪啾！啪啾！粘液随着交媾声四处飞溅。", null, "画面_黒", "bgm26", null, "After Story", null, null], [447, "", "但是我的下半身已经陷入麻痹，根本感觉不到它们的温暖。", null, "画面_黒", "bgm26", null, "After Story", null, null], [448, "憧子", "「哈啊，哈啊，哈啊啊啊啊——还没来吗？精液，还没来？啊、啊、嗯、嗯嗯嗯啊啊啊」", "tou412_179", "画面_黒", "bgm26", null, "After Story", null, null], [449, "柊史", "「就、就差一点了……再坚持一会儿很快就……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [450, "憧子", "「唔唔唔、啊啊啊啊啊啊！哈啊——哈啊——不行……我不行了……我已经忍不住了……啊、啊、啊、啊、放过我吧，放过我吧」", "tou412_180", "画面_黒", "bgm26", null, "After Story", null, null], [451, "憧子", "「明明刚才已经高潮了那么多次，又要……啊，啊，啊，啊啊啊啊啊……要去了，又要去了啊」", "tou412_181", "画面_黒", "bgm26", null, "After Story", null, null], [452, "柊史", "「没事的。我也很快会跟上你的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [453, "憧子", "「可是……唔唔唔啊啊啊哈啊，哈啊，哈啊，我明明好想要精液……可是我又自顾自高潮了……啊，啊，啊，要去了」", "tou412_182", "画面_黒", "bgm26", null, "After Story", null, null], [454, "憧子", "「对不起，对不起，我又要去了，啊啊啊啊啊，去了去了去了唔唔唔唔唔——唔唔啊啊啊啊啊——！」", "tou412_183", "画面_黒", "bgm26", null, "After Story", null, null], [455, "", "憧子再度迎来了高潮。", null, "画面_白", "bgm26", null, "After Story", null, null], [456, "", "不知是因为长时间的忍耐，还是因为前几次口交高潮的累加效果，无比激烈的高潮让她的身体扭得整个人都差点翻了个个儿。", null, "画面_白", "bgm26", null, "After Story", null, null], [457, "", "穴内的情况也大差不差，连粘膜都反复抽搐着箍住阴茎死死不放——", null, "画面_白", "bgm26", null, "After Story", null, null], [458, "柊史", "「咕唔唔唔啊啊、憧、憧子，我要射了」", null, "画面_白", "bgm26", null, "After Story", null, null], [459, "", "——咕嘟！咕嘟，咕嘟！", null, "画面_黒", "bgm26", null, "After Story", null, null], [460, "", "我在憧子体内猛烈射精，射到全身都几乎要使不上劲了。", null, "画面_黒", "bgm26", null, "After Story", null, null], [461, "憧子", "「嗯啊、啊、啊、啊啊啊啊啊啊……射进来了，滚烫的，粘稠的精液咻地射进了我里面……哈、哈、哈啊啊」", "tou412_184", "画面_黒", "bgm26", null, "After Story", null, null], [462, "憧子", "「好多……真的射了好多……哈、哈、哈啊啊啊……这种射法，不怀孕才怪呢……哈啊啊啊啊」", "tou412_185", "画面_黒", "bgm26", null, "After Story", null, null], [463, "", "憧子一边看着结合部，一边满足地叹了口气。", null, "画面_黒", "bgm26", null, "After Story", null, null], [464, "柊史", "「哈啊，哈啊，哈啊……射得太猛了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [465, "憧子", "「嗯。哈啊——哈啊——谢谢你为我射了这么多……啊、哈啊啊啊……」", "tou412_186", "画面_黒", "bgm26", null, "After Story", null, null], [466, "憧子", "「啊啊。一直流到最里面了……嗯、嗯嗯……真的好厉害……」", "tou412_187", "画面_黒", "bgm26", null, "After Story", null, null], [467, "柊史", "「呃、唔唔唔……你里面还在不停抽动……小穴就像在吸着我一样」", null, "画面_黒", "bgm26", null, "After Story", null, null], [468, "", "粘膜试图从刚射完精的阴茎中榨取更多的精液。", null, "画面_黒", "bgm26", null, "After Story", null, null], [469, "", "……这样下去的话，我又会……", null, "画面_黒", "bgm26", null, "After Story", null, null], [470, "憧子", "「哈啊……哈啊……哈啊……啊、哎？等等，别动啊，现在动的话……啊、啊、啊、啊、啊啊啊啊啊啊——！」", "tou412_188", "画面_黒", "bgm26", null, "After Story", null, null], [471, "憧子", "「不，不可以动……哈啊，哈啊，那样不行，嗯啊嗯啊，精液都要被刮出去了……唔唔……啊啊啊啊啊！」", "tou412_189", "画面_黒", "bgm26", null, "After Story", null, null], [472, "柊史", "「没关系。刮出去多少，我就再射进去多少」", null, "画面_黒", "bgm26", null, "After Story", null, null], [473, "", "刚刚射进里面的精液随着我的抽送不断滴落出来。", null, "画面_黒", "bgm26", null, "After Story", null, null], [474, "", "但我丝毫没在意，只是激烈地摩擦着粘膜。", null, "画面_黒", "bgm26", null, "After Story", null, null], [475, "", "——嘟咻！嘟啾，嘟啾啾！", null, "画面_黒", "bgm26", null, "After Story", null, null], [476, "", "我猛地把腰一抽，让积攒已久的精液喷溅在憧子的身体上。", null, "画面_黒", "bgm26", null, "After Story", null, null], [477, "憧子", "「嗯啊、啊……啊啊啊啊……哈、哈啊，哈啊，啊，讨厌……嗯、精液，都喷在身上了……嗯」", "tou412_190", "画面_黒", "bgm26", null, "After Story", null, null], [478, "憧子", "「真是的……为什么不射在里面呢……？你不想要孩子吗？」", "tou412_191", "画面_黒", "bgm26", null, "After Story", null, null], [479, "", "随着一阵剧烈的哆嗦而射出的精液，也沾满了我自己的阴茎。", null, "画面_黒", "bgm26", null, "After Story", null, null], [480, "", "憧子抬头看着此情此景，露出了一脸不满意的表情。", null, "画面_黒", "bgm26", null, "After Story", null, null], [481, "柊史", "「不，我想要我们的孩子」", null, "画面_黒", "bgm26", null, "After Story", null, null], [482, "憧子", "「那么……你就应该好好射在里面……嗯嗯」", "tou412_192", "画面_黒", "bgm26", null, "After Story", null, null], [483, "柊史", "「但这就射在里面的话，我感觉太可惜了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [484, "憧子", "「可惜……？」", "tou412_193", "画面_黒", "bgm26", null, "After Story", null, null], [485, "柊史", "「是的。我还想再好好爽爽……我……」", null, "画面_黒", "bgm26", null, "After Story", null, null], [486, "", "——滋噜噜。", null, "画面_黒", "bgm26", null, "After Story", null, null], [487, "", "沾满了精液的阴茎又再次插入了憧子体内。", null, "画面_黒", "bgm26", null, "After Story", null, null], [488, "", "阴茎很顺利地就没入其中。于是我再度用前端磨蹭粘膜。", null, "画面_黒", "bgm26", null, "After Story", null, null], [489, "憧子", "「哎？啊，等一下……啊、啊、啊、啊、啊啊啊啊……？！」", "tou412_194", "画面_黒", "bgm26", null, "After Story", null, null], [490, "柊史", "「这次我会好好射在里面的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [491, "憧子", "「嗯嗯、啊啊啊啊啊啊！啊、啊、啊、啊啊啊啊啊！又，顶到了……啊嗯，啊嗯，啊啊啊啊啊啊嗯」", "tou412_195", "画面_黒", "bgm26", null, "After Story", null, null], [492, "憧子", "「啊、不行……那样……啊，啊，啊，啊咿，好、好激烈……嗯、嗯啊——嗯啊——！」", "tou412_196", "画面_黒", "bgm26", null, "After Story", null, null], [493, "柊史", "「想高潮的话，你随时都可以高潮的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [494, "憧子", "「别、别啊啊啊——啊啊……嗯咿，哈咿……啊啊啊，一直在磨蹭，啊，啊，啊，我的小穴，一直在被精液磨蹭着」", "tou412_197", "画面_黒", "bgm26", null, "After Story", null, null], [495, "柊史", "「这样弄比起射在里面，是不是感觉更容易怀上？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [496, "憧子", "「话是这么说没错……啊啊啊，啊啊啊……太舒服了……啊、啊、啊啊啊……哈啊，哈啊，啊啊啊——！」", "tou412_198", "画面_黒", "bgm26", null, "After Story", null, null], [497, "柊史", "「我会让你变得更容易怀孕的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [498, "憧子", "「就算是这样，凡事都讲究个限度……哈啊，哈啊，哈啊……又要变成下流的怪表情了……唔唔唔啊啊啊」", "tou412_199", "画面_黒", "bgm26", null, "After Story", null, null], [499, "柊史", "「真的不怪。很可爱的，我最喜欢了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [500, "", "憧子张大嘴巴，拼命索求着氧气。", null, "画面_黒", "bgm26", null, "After Story", null, null], [501, "", "而我还是固执地磨蹭着，就像是不想让她好好呼吸一样。", null, "画面_黒", "bgm26", null, "After Story", null, null], [502, "憧子", "「呀、啊、啊、啊啊啊啊————！那里，不行，那是个奇怪的开关，要是按下去的话……啊、啊、啊——」", "tou412_200", "画面_黒", "bgm26", null, "After Story", null, null], [503, "憧子", "「啊，啊，啊————好舒服……为什么会这么舒服啊，我明明已经高潮了不知道多少遍了」", "tou412_201", "画面_黒", "bgm26", null, "After Story", null, null], [504, "", "口水、汗水、白浊的爱液在憧子的剧烈颤抖中被甩得到处都是，散发出浓烈的雌性气味。", null, "画面_黒", "bgm26", null, "After Story", null, null], [505, "", "这说明了她有多么兴奋……而闻了这种味道的我也……！", null, "画面_黒", "bgm26", null, "After Story", null, null], [506, "憧子", "「啊啊、啊啊啊——啊啊啊……好、好棒，鸡鸡好舒服……哈咿、哈咿、嗯嗯嗯——嗯！」", "tou412_202", "画面_黒", "bgm26", null, "After Story", null, null], [507, "憧子", "「哈啊，哈啊，哈啊……小穴好麻……唔唔啊啊啊，不可以顶来顶去……啊、啊、这样下去又要去了啦」", "tou412_203", "画面_黒", "bgm26", null, "After Story", null, null], [508, "柊史", "「别再忍耐了。尽情高潮吧。我也马上要射了，我会用我的精液把你里面填得满满的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [509, "憧子", "「嗯，哈啊哈啊哈啊，射吧……射给我吧，在我的肚子里全都射出来，给我受精吧……啊、啊啊啊啊啊啊啊啊」", "tou412_204", "画面_黒", "bgm26", null, "After Story", null, null], [510, "憧子", "「啊啊、今天真的，不行了……真的要疯了，才刚高潮过……哈啊，哈啊，哈啊，啊啊，这就又要去了……啊啊啊啊啊」", "tou412_205", "画面_黒", "bgm26", null, "After Story", null, null], [511, "柊史", "「我也是……刚才的余韵犹存……咕唔唔啊啊」", null, "画面_黒", "bgm26", null, "After Story", null, null], [512, "憧子", "「好厉害、太厉害了，啊——！要傻掉了，小穴要傻掉了……嗯咿，嗯咿……哈啊，哈啊，哈啊啊啊啊——！」", "tou412_206", "画面_黒", "bgm26", null, "After Story", null, null], [513, "", "憧子的表情变得更加扭曲了。", null, "画面_黒", "bgm26", null, "After Story", null, null], [514, "", "但是现在的我已经没空去欣赏那个表情了。", null, "画面_黒", "bgm26", null, "After Story", null, null], [515, "憧子", "「哈啊，哈啊，啊、啊啊——好、好棒……好爽……不行了……我，我受不了了……」", "tou412_207", "画面_黒", "bgm26", null, "After Story", null, null], [516, "憧子", "「哈咿、哈咿……要去了，啊啊啊，要去了……射吧，快啊快啊，哈啊，哈啊，嗯、嗯、嗯嗯、啊呀啊啊！」", "tou412_208", "画面_黒", "bgm26", null, "After Story", null, null], [517, "柊史", "「我要射了，这就要射了。再让我多看看你下流的表情」", null, "画面_黒", "bgm26", null, "After Story", null, null], [518, "憧子", "「小柊，你也让我看看。看看你下流的表情……然后在小穴里咻咻咻地种下很多精子……啊、啊、啊、啊，啊……嗯嗯嗯！」", "tou412_209", "画面_黒", "bgm26", null, "After Story", null, null], [519, "柊史", "「啊、啊啊啊……要射了，射了，憧子！我要射进去了！」", null, "画面_黒", "bgm26", null, "After Story", null, null], [520, "憧子", "「嗯啊啊啊！啊咿、啊、啊、我、已经不行了……啊啊啊啊，去了去了去了……！」", "tou412_210", "画面_黒", "bgm26", null, "After Story", null, null], [521, "柊史", "「憧、憧子！」", null, "画面_黒", "bgm26", null, "After Story", null, null], [522, "憧子", "「呀啊啊啊啊啊啊啊啊————啊啊！」", "tou412_211", "画面_黒", "bgm26", null, "After Story", null, null], [523, "", "在憧子发出高叫的同时，我的阴茎也到达极限，放开了精关。", null, "画面_黒", "bgm26", null, "After Story", null, null], [524, "", "咕嘟咕嘟！咕嘟！", null, "画面_黒", "bgm26", null, "After Story", null, null], [525, "", "大量的精液灌注入憧子体内，根本不像已经射过好几次的样子。", null, "画面_黒", "bgm26", null, "After Story", null, null], [526, "憧子", "「哈呀、哈、哈啊啊——哈啊啊，哈啊啊——啊……哈啊——哈啊——高潮了，我又高潮了……」", "tou412_212", "画面_黒", "bgm26", null, "After Story", null, null], [527, "柊史", "「我也射了，射得太猛烈了」", null, "画面_黒", "bgm26", null, "After Story", null, null], [528, "憧子", "「嗯，我知道……嗯嗯。因为我的里面都灌满了啊。感觉真的要被烫伤了……唔啊，哈啊——哈啊——」", "tou412_213", "画面_黒", "bgm26", null, "After Story", null, null], [529, "柊史", "「……嗯嗯」", null, "画面_黒", "bgm26", null, "After Story", null, null], [530, "", "我从憧子体内缓缓地抽出阴茎。", null, "画面_黒", "bgm26", null, "After Story", null, null], [531, "", "阴茎顺着水流滑了出来。", null, "画面_黒", "bgm26", null, "After Story", null, null], [532, "", "憧子的粘膜没了阴茎这个塞子，便开始一张一闭地将其中的精液吐了出来。", null, "画面_黒", "bgm26", null, "After Story", null, null], [533, "憧子", "「啊、不行、啊啊啊……流出来了，好不容易射进去的精液都流出来了……」", "tou412_214", "画面_黒", "bgm26", null, "After Story", null, null], [534, "柊史", "「没事的。流出来的都是灌满了多出来的」", null, "画面_黒", "bgm26", null, "After Story", null, null], [535, "憧子", "「那就是说都有流到里面去吗？」", "tou412_215", "画面_黒", "bgm26", null, "After Story", null, null], [536, "柊史", "「当然有。如果没有的话……到时我会再射进去的。射多少次都行」", null, "画面_黒", "bgm26", null, "After Story", null, null], [537, "柊史", "「其实我想说……现在就再来一回，可以吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [538, "憧子", "「哎，哎哎哎……你的精力也太旺盛了吧……」", "tou412_216", "画面_黒", "bgm26", null, "After Story", null, null], [539, "柊史", "「还是说……不行吗？」", null, "画面_黒", "bgm26", null, "After Story", null, null], [540, "憧子", "「……唔……你得让我先缓一缓。这样的话……我应该还能再努力一下」", "tou412_217", "画面_黒", "bgm26", null, "After Story", null, null], [541, "柊史", "「好，那就拜托了！」", null, "画面_黒", "bgm26", null, "After Story", null, null], [542, "", "我们就这样黏糊着，互相索求着，一直到迎来早晨。", null, "空_夜空", "bgm26", null, "After Story", null, null], [543, "憧子", "「唔……好刺眼……」", "tou412_218", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "18", "pose": "2"}, "After Story", null, null], [544, "柊史", "「是啊」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "18", "pose": "2"}, "After Story", null, null], [545, "", "太阳好像已经开始泛黄了。", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "18", "pose": "2"}, "After Story", null, null], [546, "憧子", "「不过真的射了好多啊……也不知道有没有怀上」", "tou412_219", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "16", "pose": "3"}, "After Story", null, null], [547, "柊史", "「这种事讲究的是时机。如果这次没怀上，以后机会还多得是」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "16", "pose": "3"}, "After Story", null, null], [548, "憧子", "「……嗯」", "tou412_220", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "25h", "pose": "2"}, "After Story", null, null], [549, "柊史", "「然后呢，憧子」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "25h", "pose": "2"}, "After Story", null, null], [550, "憧子", "「怎么了？」", "tou412_221", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "19", "pose": "1"}, "After Story", null, null], [551, "柊史", "「昨天我光想着婚礼之类的事了……其实那之后的事也该考虑起来了吧？」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "19", "pose": "1"}, "After Story", null, null], [552, "柊史", "「所以今天我们去看看可以两个人住的房子吧？还要去拿一份婚姻登记表」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "19", "pose": "1"}, "After Story", null, null], [553, "憧子", "「……也是。这些事确实没考虑到，就这么办吧」", "tou412_222", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "02", "pose": "1"}, "After Story", null, null], [554, "憧子", "「可是小柊，房子可能很快就要三个人住了哦」", "tou412_223", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "02", "pose": "1"}, "After Story", null, null], [555, "柊史", "「对哦，也是。那就去找找三个人住的房子吧」", null, "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "02", "pose": "1"}, "After Story", null, null], [556, "憧子", "「嗯！」", "tou412_224", "外_繁華街モブa", "bgm34", {"char": "憧子", "dress": "デート服", "face": "15", "pose": "3"}, "After Story", null, null]];
